def clean_tags(text):
    tags = []
    for line in text.splitlines():
        tag = line.strip().lower().replace(" ", "-")
        if tag != "" and tag not in tags:
            tags.append(tag)
    return sorted(tags)

print(clean_tags(" Ada \nBo\nada\n \nCee Dee"))
